import java.util.List;

class Example {
    static void a(long value) { }
    static void a(int value) { }
    static void b(long value) { }
    static void b(short value) { }
    static void c(int value) { }
    static <T> T c(long value) { return null; }
    static void d(Number value) { }
    static <T> void d(T value) { }
    static void e(int value, Runnable task) { }
    static void e(long value, Runnable task) { }
    static void k(int value, List<String> names) { }
    static <T> void k(long value, List<T> names) { }
    void test(Integer value, long limit, List<String> names) {
        a(value.intValue()); // a(int) is more specific than a(long)
        b(value.longValue()); // int cannot be widened to short
        Math.max(value.longValue(), limit); // Math.max(int, int) cannot take the long argument
        c(value.intValue()); // c(int) is more specific than the generic c(long)
        d(value.intValue()); // d(Number) is more specific than d(T)
        e(value.intValue(), () -> { }); // e(int, Runnable) is more specific than e(long, Runnable)
        k(value.intValue(), names); // k(int, List<String>) is more specific than the generic k(long, List<T>)
    }
}

import java.util.ArrayList;
import java.util.List;
class Box<T> {
    Box(int capacity) { }
    Box(T value) { }
    class Inner<E> {
        Inner(int capacity) { }
        Inner(T value) { }
    }
    static void test(Integer value, Box<Integer> box) {
        Box<String> a = new Box<>(value.intValue()); // without intValue(), Box(T) would be selected and T could not be inferred
        Box<String> b = new Box<String>(value.intValue()); // Integer cannot be passed to Box(String)
        List<String> c = new ArrayList<>(value.intValue()); // Integer cannot be passed to ArrayList(Collection)
        Box<Integer>.Inner<String> d = box.new Inner<>(value.intValue()); // Inner(T) with T = Integer would be selected without intValue()
    }
}

import static java.lang.Math.abs;

class Example {
    static class Base {
        Base(int value) { }
        Base(Object value) { }
        void m(double value) { }
        static void z(Object value) { }
    }
    static class Sub extends Base {
        Sub(int value) {
            super(value);
        }
        Sub(Object value) {
            super(value);
        }
        Sub(Integer value, boolean flag) {
            this(value.intValue()); // Sub(Object) would be selected without intValue()
        }
        Sub(Integer value, String name) {
            super(value.intValue()); // Base(Object) would be selected without intValue()
        }
        void m(int value) { }
        static void z(int value) { }
    }
    class Middle {
        void m(int value) { }
        class Inner {
            void test(Integer value) {
                m(value.intValue()); // only Middle.m(int) is searched, not Example.m(Object)
            }
        }
    }
    interface Api {
        static void v(int value) { }
        static void v(Object value) { }
        default void w(Object value) { }
    }
    static class Impl implements Api {
        static void v(int value) { }
        void w(int value) { }
        void test(Integer value) {
            v(value.intValue()); // static interface methods are not inherited, so only Impl.v(int) is searched
        }
    }
    static void m(Object value) { }
    static void s(int value) { }
    void s(Object value) { }
    void test(Sub sub, Integer value) {
        sub.m(value.doubleValue()); // Sub.m(int) would be selected without doubleValue()
        new Base(0) { void m(Object other) { } }.m(value.doubleValue()); // m(Object) would be selected without doubleValue()
        Example.s(value.intValue()); // the instance method s(Object) would be selected without intValue()
        abs(value.longValue()); // Math.abs(int) would be selected without longValue()
        new Counter(value.intValue()); // Counter(Object) is private
        Impl.v(value.intValue()); // Api.v(Object) is not a member of Impl
        Api.v(value.intValue()); // Api.v(Object) would be selected without intValue()
        Sub.z(value.intValue()); // the inherited static method Base.z(Object) would be selected without intValue()
        new Impl().w(value.intValue()); // the inherited default method Api.w(Object) would be selected without intValue()
    }
}
class Counter {
    static final Integer START = 0;
    Counter(int start) { }
    private Counter(Object start) { }
}
enum Kind {
    A(Counter.START.intValue()); // Kind(Object) would be selected without intValue()
    Kind(int value) { }
    Kind(Object value) { }
}

