    static void a(int... values) { }
    static void b(long first, String... rest) { }
    static void b(Integer... values) { }
    static void c(long... values) { }
    static void c(Integer value) { }
    static void d(int... values) { }
    static void d(long... values) { }
    static void e(long... values) { }
    static void e(double... values) { }
    static void e(Object first, Object second) { }
    static void e(Object first, Object second, Object... rest) { }
    static void f(int value, Callable<String> task) { }
    static void f(Object value, Callable<String> task) { }
    static void f(int value, Runnable... tasks) { }
    void test(Integer value) {
        a(value.longValue()); // a(int...) would be selected without longValue()
        b(value.longValue()); // the call would be ambiguous without longValue()
        c(value.longValue()); // c(Integer) would be selected without longValue()
        d(value.intValue()); // d(int...) is more specific than d(long...)
        e(value.longValue()); // e(long...) is more specific than e(double...), and the other overloads of e take at least two arguments
        f(value.intValue(), () -> { while (true) { } }); // f(Object, Callable) would be selected without intValue()
    }
}

import java.util.Comparator;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;

class Example {
    static String text;
    static Integer count;
    static final boolean ON = true;
    static void f(int value, Runnable task) { }
    static void f(Integer value, Supplier<String> task) { }
    static void g(int value, Supplier<Object> task) { }
    static void g(Integer value, Runnable task) { }
    static void h(int value, Consumer<String> task) { }
    static void h(Integer value, Function<String, String> task) { }
    static void j(int value, Supplier<Object> task) { }
    static void j(Integer value, Supplier<String> task) { }
    static void k(int value, Runnable task) { }
    static void k(Integer value, Runnable task) { }
    static void o(int value, Runnable task) { }
    static void o(Integer value, Object task) { }
    static void o(Integer value, Comparator<String> task) { }
    static void r(int value, Consumer<List<String>> task) { }
    static void r(Integer value, Function<List<String>, String> task) { }
    static void t(int value, Runnable task) { }
    static <T> void t(Integer value, T task) { }
    static class Task {
        void stop() { }
    }
    static class TimedTask extends Task {
        String stop(int timeout) { return ""; }
    }
    static String text() { return ""; }
    static void run() { }
    static void name() { }
    static String name(int index) { return ""; }
    static void runAll(String... names) { }
    static <T> void runGeneric() { }
    void test(Integer value, final boolean flag, TimedTask task) {
        f(value.intValue(), Example::run); // run() returns no value for Supplier
        f(value.intValue(), () -> { throw new IllegalStateException(); }); // f(Integer, Supplier) would be selected without intValue()
        f(value.intValue(), () -> { while (true) { for (;;) { break; } } }); // f(Integer, Supplier) would be selected without intValue()
        f(value.intValue(), () -> { while (true) { break; } }); // the lambda body can complete normally, so it returns no value for Supplier
        f(value.intValue(), () -> { while (text == null) { } }); // the lambda body can complete normally, so it returns no value for Supplier
        f(value.intValue(), () -> { while (flag) { } }); // flag is not a constant variable, so the lambda body can complete normally
        f(value.intValue(), () -> { for (String name : List.of(text)) { } }); // the lambda body can complete normally, so it returns no value for Supplier
        f(value.intValue(), () -> { while (true) { return; } }); // the lambda returns no value for Supplier
        f(value.intValue(), () -> { while (1 < 2) { } }); // f(Integer, Supplier) would be selected without intValue()
        f(value.intValue(), () -> { while ((boolean) true) { } }); // f(Integer, Supplier) would be selected without intValue()
        f(value.intValue(), () -> { while (ON == true) { } }); // f(Integer, Supplier) would be selected without intValue()
        f(value.intValue(), Example::name); // f(Integer, Supplier) would be selected without intValue(), with name() returning no value
        f(value.intValue(), Example::runAll); // f(Integer, Supplier) would be selected without intValue(), with runAll(String...) returning no value
        f(value.intValue(), Example::runGeneric); // f(Integer, Supplier) would be selected without intValue(), with runGeneric() returning no value
        f(value.intValue(), task::stop); // f(Integer, Supplier) would be selected without intValue(), with stop() returning no value
        g(value.intValue(), () -> -count); // the lambda body is not a statement for Runnable
        g(value.intValue(), () -> (text())); // a parenthesized expression is not a statement for Runnable
        g(value.intValue(), () -> { return text(); }); // the lambda returns a value for Runnable
        g(value.intValue(), () -> text()); // g(Integer, Runnable) would be selected without intValue()
        g(value.intValue(), () -> new StringBuilder()); // g(Integer, Runnable) would be selected without intValue()
        g(value.intValue(), () -> text = "x"); // g(Integer, Runnable) would be selected without intValue()
        g(value.intValue(), () -> count++); // g(Integer, Runnable) would be selected without intValue()
        g(value.intValue(), flag ? () -> text() : null); // g(Integer, Runnable) would be selected without intValue()
        h(value.intValue(), (String s) -> System.out.println(s)); // the explicitly typed lambda returns no value for Function
        h(value.intValue(), s -> System.out.println(s)); // h(Integer, Function) would be selected without intValue(), and the lambda would not compile
        h(value.intValue(), System.out::println); // h(Integer, Function) would be selected without intValue(), and the method reference would not compile
        j(value.intValue(), () -> { return text(); }); // j(Integer, Supplier<String>) would be selected without intValue()
        j(value.intValue(), Example::text); // j(Integer, Supplier<String>) would be selected without intValue()
        k(value.intValue(), Example::run); // k(Integer, Runnable) would be selected without intValue()
        o(value.intValue(), () -> text()); // the lambda fits neither Object nor Comparator
        r(value.intValue(), List::clear); // r(Integer, Function) would be selected without intValue(), and the method reference would not compile
        t(value.intValue(), () -> { }); // t(Integer, T) would be selected without intValue(), and T could not be inferred
    }
}

