class Example {
    static class Mine extends Base { }
    static <T> T any() { return null; }
    static <T> T[] array() { return null; }
    static String text() { return ""; }
    static void a(int value, Runnable task) { }
    static void a(Integer value, Runnable task) { }
    static <T extends Number & Runnable> void b(int value, T task) { }
    static void b(long value, Runnable task) { }
    static void c(int value, int number) { }
    static void c(Integer value, char letter) { }
    static void m(int value, String text) { }
    static void m(Integer value, Integer number) { }
    static void p(int value, long number) { }
    static void p(Integer value, String text) { }
    static void q(int value, List<String> list) { }
    static void q(Integer value, List<Integer> list) { }
    static void r(int value, Integer number) { }
    static void r(Integer value, int number) { }
    static void t(int value, long number) { }
    static void t(Integer value, Long number) { }
    static void u(int value, Runnable task) { }
    static void u(Integer value, Task task) { }
    static void v(int value, Object object) { }
    static void v(Integer value, long number) { }
    static void w(int value, Object object) { }
    static void w(Integer value, Lib lib) { }
    static void x(int value, Object[] array) { }
    static void x(Integer value, String[] array) { }
    static void y(int value, Object object) { }
    static void y(Integer value, List<Integer> list) { }
    static void z(int value, Object object) { }
    static void z(Integer value, Type type) { }
    <N extends Integer, R extends Number & Runnable> void test(Integer value, boolean flag, int n, N number, Mine mine, int[] numbers, StringBuilder builder, String name, String[] names, Class rawType, R task) {
        m(value.intValue(), any()); // m(Integer, Integer) would be selected without intValue()
        m(value.intValue(), null); // m(Integer, Integer) would be selected without intValue()
        m(value.intValue(), flag ? any() : null); // m(Integer, Integer) would be selected without intValue()
        m(value.intValue(), flag ? text() : null); // the String operand cannot be passed to m(Integer, Integer)
        m(value.intValue(), switch (n) { case 0 -> any(); default -> null; }); // m(Integer, Integer) would be selected without intValue()
        m(value.intValue(), switch (n) { case 0 -> text(); default -> null; }); // the String result cannot be passed to m(Integer, Integer)
        m(value.intValue(), Example.<String>any()); // the String argument cannot be passed to m(Integer, Integer)
        m(value.intValue(), text()); // the String argument cannot be passed to m(Integer, Integer)
        m(value.intValue(), Objects.requireNonNull(name)); // the String argument cannot be passed to m(Integer, Integer)
        p(value.intValue(), flag ? 1 : 2); // the int argument cannot be passed to p(Integer, String)
        c(value.intValue(), flag ? 'a' : 1); // c(Integer, char) would be selected without intValue()
        c(value.intValue(), flag ? 'a' : n); // the int argument cannot be passed to c(Integer, char)
        q(value.intValue(), new ArrayList<>()); // q(Integer, List<Integer>) would be selected without intValue()
        x(value.intValue(), array()); // x(Integer, String[]) would be selected without intValue()
        x(value.intValue(), Objects.requireNonNullElse(names, array())); // x(Integer, String[]) would be selected without intValue()
        y(value.intValue(), array()); // an array cannot be passed to y(Integer, List<Integer>)
        builder.insert(value.intValue(), List.of(1)); // the List argument can only be passed to insert(int, Object)
        Arrays.copyOf(numbers.clone(), value.intValue()); // the int[] argument can only be passed to copyOf(int[], int)
        r(value.intValue(), number); // the call would be ambiguous without intValue()
        r(value.intValue(), flag ? value : null); // the call would be ambiguous without intValue()
        r(value.intValue(), null); // null cannot be passed to r(Integer, int)
        r(value.intValue(), Lib.COUNT); // the call may be ambiguous without intValue()
        t(value.intValue(), flag ? 1 : 2L); // the call would be ambiguous without intValue()
        t(value.intValue(), switch (n) { case 0 -> 1; default -> 2L; }); // the int result cannot be passed to t(Integer, Long)
        t(value.intValue(), Lib.count() + 1); // the call may be ambiguous without intValue()
        u(value.intValue(), () -> { }); // u(Integer, Task) may be selected without intValue()
        w(value.intValue(), mine); // w(Integer, Lib) may be selected without intValue()
        v(value.intValue(), new Base()); // a Base cannot be passed to v(Integer, long)
        z(value.intValue(), rawType); // z(Integer, Type) would be selected without intValue()
        a(value.intValue(), task); // a(Integer, Runnable) would be selected without intValue()
        b(value.intValue(), task); // b(int, T) is more specific than b(long, Runnable)
    }
}

import net.sourceforge.pmd.lang.java.rule.codestyle.unnecessaryboxing.ProtectedConstructor;

class Example {
    void test(Integer value) {
        new ProtectedConstructor(value.intValue()); // ProtectedConstructor(Object) is not accessible here
        new ProtectedConstructor(value.intValue()) { }; // ProtectedConstructor(Object) would be selected without intValue()
    }
}
